class Solution:
    def smallestGoodBase(self, n: str) -> str:
        num = int(n)

        def eq(k, m):
            s = p = 1
            for _ in range(m - 1):
                p *= k
                s += p
                if s > num:
                    return False
            return s == num

        for m in range(num.bit_length(), 1, -1):
            lo, hi = 2, num - 1
            while lo < hi:
                mid = (lo + hi) // 2
                s = p = 1
                big = False
                for _ in range(m - 1):
                    p *= mid
                    s += p
                    if s >= num:
                        big = True
                        break
                if big or s < num:
                    lo = mid + 1
                else:
                    hi = mid
            if eq(lo, m):
                return str(lo)
        return str(num - 1)

