var smallestGoodBase = function(n) {
    const num = BigInt(n);
    const eq = (k, m) => {
        let s = 1n, p = 1n;
        for (let i = 1; i < m; i++) {
            p *= k; s += p;
            if (s > num) return false;
        }
        return s === num;
    };
    let bits = 0, t = num;
    while (t > 0n) { bits++; t >>= 1n; }
    for (let m = bits; m >= 2; m--) {
        let lo = 2n, hi = num - 1n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1n;
            let s = 1n, p = 1n, big = false;
            for (let i = 1; i < m; i++) {
                p *= mid; s += p;
                if (s >= num) { big = true; break; }
            }
            if (big || s < num) lo = mid + 1n;
            else hi = mid;
        }
        if (eq(lo, m)) return lo.toString();
    }
    return (num - 1n).toString();
};

